export function listSifAuthorities(cpId?: SifCpId): readonly SifScenarioAuthority[] {
  return cpId ? SIF_SCENARIO_AUTHORITIES.filter((entry) => entry.cpId === cpId) : SIF_SCENARIO_AUTHORITIES;
}
